   408|// ── GitHub side-branch ledger persistence (no Supabase service key needed) ──
   409|// The ledger is committed to a NON-deploy branch so Render autoDeploy (which
   410|// watches main) never fires from a ledger write. No secrets are stored.
   411|
   412|const LEDGER_GITHUB_BRANCH = 'ivx-proof-ledger';
   413|const DEFAULT_LEDGER_REPO = 'ibb142/rork-global-real-estate-invest';
   414|
   415|function ledgerGithubToken(): string {
   416|  return typeof process.env.GITHUB_TOKEN === 'string' ? process.env.GITHUB_TOKEN.trim() : '';
   417|}
   418|
   419|function ledgerGithubRepo(): string {
   420|  const raw = typeof process.env.GITHUB_REPO === 'string' ? process.env.GITHUB_REPO.trim() : '';
   421|  const match = raw.match(/([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+?)(?:\.git)?$/);
   422|  if (match && match[1].includes('/')) return match[1];
   423|  return DEFAULT_LEDGER_REPO;
   424|}
