   437|  try {
   438|    const res = await fetch(
   439|      `https://api.github.com/repos/${ledgerGithubRepo()}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   440|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   441|    );
   442|    if (!res.ok) return null;
   443|    const data = await res.json() as { content?: string };
   444|    if (!data.content) return null;
   445|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   446|    const doc = JSON.parse(decoded) as LedgerDoc;
   447|    if (!Array.isArray(doc.entries)) return null;
   448|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   449|  } catch {
   450|    return null;
   451|  }
