   454|async function githubEnsureLedgerBranch(): Promise<boolean> {
   455|  const repo = ledgerGithubRepo();
   456|  try {
   457|    const refRes = await fetch(
   458|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   459|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   460|    );
   461|    if (refRes.ok) return true;
   462|    const mainRes = await fetch(
   463|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   464|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   465|    );
   466|    if (!mainRes.ok) return false;
   467|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   468|    const baseSha = mainData.object?.sha;
   469|    if (!baseSha) return false;
   470|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   471|      method: 'POST',
   472|      headers: ledgerGithubHeaders(),
   473|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   474|      signal: AbortSignal.timeout(10000),
   475|    });
   476|    return createRes.ok;
