   482|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   483|  const token = ledgerGithubToken();
   484|  if (!token) return false;
   485|  const repo = ledgerGithubRepo();
   486|  try {
   487|    if (!(await githubEnsureLedgerBranch())) return false;
   488|    let existingSha: string | undefined;
   489|    const currentRes = await fetch(
   490|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   491|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   492|    );
   493|    if (currentRes.ok) {
   494|      const current = await currentRes.json() as { sha?: string };
   495|      existingSha = current.sha;
   496|    }
   497|    const putRes = await fetch(
   498|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   499|      {
   500|        method: 'PUT',
   501|        headers: ledgerGithubHeaders(),
   502|        body: JSON.stringify({
   503|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   504|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   505|          branch: LEDGER_GITHUB_BRANCH,
   506|          ...(existingSha ? { sha: existingSha } : {}),
   507|        }),
   508|        signal: AbortSignal.timeout(15000),
   509|      },
   510|    );
   511|    return putRes.ok;
   512|  } catch {
   513|    return false;
   514|  }
   515|}
