   517|async function appendLedger(result: IVXWorkerJobResult): Promise<void> {
   518|  // Phase 12: fingerprint the evidence and reject duplicate redeploys as
   519|  // separate completed development tasks. A duplicate fingerprint (same
   520|  // commitSha + deployId + filesChanged + finalStatus) is logged but the entry
   521|  // is still recorded (marked as duplicate) so the ledger is complete.
   522|  const fingerprint = fingerprintEvidence({
   523|    commitSha: result.commitSha,
   524|    deployId: result.deployId,
   525|    filesChanged: result.changedFiles,
   526|    finalStatus: result.finalStatus,
