   282|async function runSupabaseResetOwnerPassword(input: Record<string, unknown>): Promise<Record<string, unknown>> {
   283|  const email = readTrimmed(input.email).toLowerCase();
   284|  const newPassword = readTrimmed(input.newPassword) || readTrimmed(input.password);
   285|  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
   286|    throw new Error('A valid owner email is required for supabase_reset_owner_password.');
   287|  }
   288|  if (!newPassword || newPassword.length < 12) {
   289|    throw new Error('A new password of at least 12 characters is required for supabase_reset_owner_password (enterprise policy).');
   290|  }
   291|  const admin = resolveSupabaseAdminClient();
   292|  const { data: listData, error: listError } = await admin.auth.admin.listUsers({ page: 1, perPage: 1000 });
   293|  if (listError) {
   294|    throw new Error(`Supabase listUsers failed: ${listError.message}`);
   295|  }
   296|  const user = (listData.users ?? []).find((u) => (u.email ?? '').toLowerCase() === email);
   297|  if (!user) {
   298|    throw new Error(`No Supabase auth user found for email ${email}.`);
   299|  }
   300|  const { data: updateData, error: updateError } = await admin.auth.admin.updateUserById(user.id, {
   301|    password: newPassword,
   302|    email_confirm: true,
   303|    ban_duration: 'none',
   304|  });
   305|  if (updateError || !updateData.user) {
   306|    throw new Error(`Supabase updateUserById failed: ${updateError?.message ?? 'no user returned'}`);
   307|  }
   308|  // SECURITY: revoke all existing sessions so any session bound to the old (compromised) password is killed.
   309|  try {
   310|    await admin.auth.admin.signOut(user.id, 'global');
   311|  } catch (signOutError) {
   312|    console.log('[SupabaseResetOwnerPassword] Session revocation note:', signOutError instanceof Error ? signOutError.message : 'unknown');
   313|  }
   314|  return {
   315|    provider: 'supabase',
   316|    action: 'supabase_reset_owner_password',
   317|    email,
   318|    userId: user.id,
   319|    passwordReset: true,
   320|    sessionsRevoked: true,
   321|    emailConfirmed: Boolean(updateData.user.email_confirmed_at || updateData.user.confirmed_at) || true,
   322|    timestamp: nowIso(),
   323|    secretValuesReturned: false as const,
   324|  };
   325|}
