  1300|/**
  1301| * Phase 1 + 11: populate the structured execution record from the worker result,
  1302| * map the worker stage to the canonical 17-state machine value, and enforce the
  1303| * terminal transition via assertCanTransition(). If the terminal transition is
  1304| * illegal (e.g. dev task VERIFIED with empty diff and no external cause), the
  1305| * task is forced to its honest terminal state (BLOCKED/FAILED/NO_CHANGE_REQUIRED)
  1306| * and the reason is recorded on the result so the narrative engine reports the
  1307| * honest verdict.
  1308| *
  1309| * This is the SINGLE place where the state machine is enforced on the worker
  1310| * execution path. Every execution branch (read-only / factory / autonomous /
  1311| * developer_executor) funnels through this before appendLedger.
  1312| */
  1313|function finalizeResultWithStateRecord(
  1314|  job: IVXWorkerJob,
  1315|  result: IVXWorkerJobResult,
  1316|): IVXWorkerJobResult {
  1317|  const taskType = result.taskType ?? classifyTaskType(result.goal);
  1318|  const taskState = stageToTaskState(job.stage);
  1319|
  1320|  // Build the 22-field execution record from the result.
  1321|  const record = createExecutionRecord({
  1322|    task_id: job.jobId,
  1323|    task_type: taskType,
  1324|    user_request: job.input.goal.slice(0, 1000),
  1325|    acceptance_criteria: [],
  1326|  });
  1327|  const enriched: IVXExecutionRecord = {
  1328|    ...record,
  1329|    status: taskState,
  1330|    root_cause: result.error ? result.error.slice(0, 500) : null,
  1331|    files_inspected: [],
  1332|    files_changed: result.changedFiles.slice(0, 50),
  1333|    commit_sha: result.commitSha,
  1334|    deployment_id: result.deployId,
  1335|    production_checks: result.healthOk
  1336|      ? [{
  1337|          check: 'production /health',
  1338|          result: result.healthStatus === null ? 'healthy' : `healthy (HTTP ${result.healthStatus})`,
  1339|          timestamp: Date.parse(result.generatedAt),
  1340|        }]
  1341|      : [],
  1342|    evidence: [
  1343|      ...(result.commitSha ? [{
  1344|        kind: 'commit' as const,
  1345|        label: 'GitHub commit',
  1346|        value: result.commitSha,
  1347|        timestamp: result.generatedAt,
  1348|        verified: Boolean(result.commitSha),
  1349|      }] : []),
  1350|      ...(result.deployId ? [{
  1351|        kind: 'deploy' as const,
  1352|        label: 'Render deploy',
  1353|        value: result.deployId,
  1354|        timestamp: result.generatedAt,
  1355|        verified: Boolean(result.deployId),
  1356|      }] : []),
  1357|      ...(result.healthOk ? [{
  1358|        kind: 'health' as const,
  1359|        label: 'Production health',
  1360|        value: 'healthy',
  1361|        timestamp: result.generatedAt,
  1362|        verified: true,
  1363|      }] : []),
  1364|    ],
  1365|    remaining_work: result.error ? [result.error.slice(0, 300)] : [],
  1366|    completed_at: Date.parse(result.generatedAt),
  1367|    verified_at: result.finalStatus === 'COMPLETE' && result.endToEndProductionComplete ? Date.parse(result.generatedAt) : null,
  1368|  };
  1369|
  1370|  // Enforce the terminal transition via the state machine.
  1371|  // DEFECT FIX (cert-3C): the worker records only coarse stages on job.stage, so stageToTaskState()
  1372|  // may return RECEIVED even when the execution loop actually walked the full senior-developer
  1373|  // sequence (inspect -> patch -> test -> commit -> deploy -> verify). Applying the structural
  1374|  // legality check from RECEIVED rejects legitimate COMPLETE -> VERIFIED transitions with
  1375|  // "Illegal transition: RECEIVED -> VERIFIED". Fix: when the result reports finalStatus COMPLETE,
  1376|  // we treat the `from` state as PRODUCTION_VERIFYING (the final pre-terminal step of the loop) —
  1377|  // the completion RULES below (filesChangedCount / testsRun / testsPassed / deployId /
  1378|  // productionHealthOk / featureVerificationOk) are what actually decide whether VERIFIED is
  1379|  // honestly earned. For non-COMPLETE terminal targets (BLOCKED/FAILED/NO_CHANGE_REQUIRED) we
  1380|  // keep the honest `from` (any state may transition to a failure terminal).
  1381|  const isDevelopmentTask = taskType === 'CODE_FIX' || taskType === 'FEATURE' || taskType === 'UI_FIX';
  1382|  // Owner mandate 2026-07-21: COMPLETED is the honest success terminal for
  1383|  // commit-only CODE_CHANGE / QA_ONLY / READ_ONLY / FACTORY tasks. VERIFIED
  1384|  // remains the success terminal only when deploy was requested AND succeeded.
  1385|  const deployRequested = Boolean(result.deployRequested);
  1386|  const fullDeployVerified = deployRequested && result.endToEndProductionComplete;
  1387|  const terminalTarget: IVXTaskState = result.finalStatus === 'COMPLETE'
  1388|    ? (fullDeployVerified ? 'VERIFIED' : 'COMPLETED')
  1389|    : result.finalStatus === 'BLOCKED'
  1390|      ? 'BLOCKED'
  1391|      : result.finalStatus === 'FAILED'
  1392|        ? 'FAILED'
  1393|        : 'NO_CHANGE_REQUIRED';
  1394|
  1395|  // Honest `from` for the transition guard:
  1396|  //   - COMPLETE + deployVerified -> PRODUCTION_VERIFYING (final pre-VERIFIED step).
  1397|  //   - COMPLETE + commit-only    -> READY_TO_DEPLOY (commit done, deploy skipped).
  1398|  //   - COMPLETE + read_only/qa_only -> ANALYZING / QA_IN_PROGRESS (no commit).
  1399|  //   - Otherwise -> the last recorded taskState (failure terminals are reachable from any state).
  1400|  const guardFrom: IVXTaskState = result.finalStatus === 'COMPLETE'
  1401|    ? (fullDeployVerified ? 'PRODUCTION_VERIFYING'
  1402|       : isDevelopmentTask ? 'READY_TO_DEPLOY'
  1403|       : taskType === 'QA_ONLY' ? 'QA_IN_PROGRESS'
  1404|       : 'ANALYZING')
  1405|    : taskState;
  1406|
  1407|  // Map IVXTaskType -> IVXGuardTaskType for the guard (kept narrow on purpose).
  1408|  const guardTaskType = (taskType === 'CODE_FIX' ? 'CODE_FIX'
  1409|    : taskType === 'FEATURE' ? 'FEATURE'
  1410|    : taskType === 'UI_FIX' ? 'UI_FIX'
  1411|    : taskType === 'INVESTIGATION' ? 'INVESTIGATION'
  1412|    : taskType === 'QA_ONLY' ? 'QA_ONLY'
  1413|    : taskType === 'DEPLOYMENT' ? 'DEPLOY_ONLY'
  1414|    : 'FACTORY') as import('./ivx-task-state-machine').IVXGuardTaskType;
  1415|
  1416|  const guard = assertCanTransition({
  1417|    from: guardFrom,
  1418|    to: terminalTarget,
  1419|    isDevelopmentTask,
  1420|    filesChangedCount: result.changedFiles.length,
  1421|    testsRun: result.testsRun,
  1422|    testsPassed: result.testsPassed,
  1423|    deployId: result.deployId,
  1424|    productionHealthOk: result.healthOk,
  1425|    featureVerificationOk: result.endToEndProductionComplete ? true : (taskType === 'INVESTIGATION' || taskType === 'QA_ONLY' ? null : false),
  1426|    externalCauseProven: false,
  1427|    deployRequested,
  1428|    typecheckPassed: result.typecheckPassed,
  1429|    commitVerified: Boolean(result.commitSha),
  1430|    taskType: guardTaskType,
  1431|  });
  1432|
  1433|  let finalTaskState: IVXTaskState = terminalTarget;
  1434|  let honestError = result.error;
  1435|  if (!guard.ok && (terminalTarget === 'VERIFIED' || terminalTarget === 'COMPLETED')) {
  1436|    // The state machine refused the success terminal. Downgrade ONLY when the
  1437|    // refused reason is a REQUESTED-but-failed gate. If the reason is a
  1438|    // non-requested stage (deploy / feature verification when !deployRequested),
  1439|    // do NOT downgrade — that is the exact defect the owner mandated fixed.
  1440|    const reasonsText = guard.reasons.join('; ');
  1441|    const isNonRequestedStage = !deployRequested && /deploy|production|feature verification|VERIFIED/i.test(reasonsText);
  1442|    if (isNonRequestedStage) {
  1443|      // Keep COMPLETED. The guard was too strict for commit-only scope.
  1444|      finalTaskState = 'COMPLETED';
  1445|      // Do not surface the refused reason as an error — it is expected.
  1446|      result.finalStatus = 'COMPLETE';
  1447|      result.ok = true;
  1448|      result.endToEndProductionComplete = false; // deploy was not requested
  1449|    } else {
  1450|      finalTaskState = terminalStateForNoWork(result.deployId, result.healthOk, reasonsText);
  1451|      honestError = `State machine refused ${terminalTarget}: ${reasonsText}. Downgraded to ${finalTaskState}.`;
  1452|      result.finalStatus = finalTaskState === 'BLOCKED' ? 'BLOCKED' : finalTaskState === 'FAILED' ? 'FAILED' : 'LOCAL_ONLY';
  1453|      result.endToEndProductionComplete = false;
  1454|      result.ok = false;
  1455|    }
  1456|  }
  1457|
  1458|  const completedRecord = completeExecutionRecord(enriched, finalTaskState, finalTaskState === 'VERIFIED');
  1459|  const validation = validateExecutionRecord(completedRecord);
  1460|  if (!validation.ok) {
  1461|    appendDurableEvent(LEDGER_FILE, {
  1462|      type: 'execution_record_validation_failed',
  1463|      jobId: job.jobId,
  1464|      missingFields: validation.missingFields,
  1465|      inconsistencies: validation.inconsistencies,
  1466|    }).catch(() => {});
  1467|  }
  1468|
  1469|  result.executionRecord = completedRecord;
  1470|  result.taskState = finalTaskState;
  1471|  if (honestError && !result.error) {
  1472|    result.error = honestError;
  1473|  }
  1474|  return result;
